#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// Sparkline's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/sparkline.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// How many of the newest values the line keeps, 2 to 100000 (std::invalid_argument outside them); a smaller capacity drops the oldest.
template <typename Declaring>
struct SparklineCapacityCapability {
    PropertyCell<std::uint32_t, SparklineCapacityCapability<Declaring>> capacity{120U};

    static void assign(SparklineCapacityCapability& capability, std::uint32_t incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.capacity), incoming);
        if (!capability.capacity.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.capacity));
    }
};

// Whether the band under the line is shaded.
template <typename Declaring>
struct SparklineFillCapability {
    PropertyCell<bool, SparklineFillCapability<Declaring>> fill{};

    static void assign(SparklineFillCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.fill), incoming);
        if (!capability.fill.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.fill));
    }
};

// Every Sparkline capability, in the order the declaring class takes them.
template <typename Declaring>
struct SparklineCapabilities : public SparklineCapacityCapability<Declaring>,
                               public SparklineFillCapability<Declaring> {};

} // namespace gui_forms
